export const TOAN_SKILLS: Skill[] = ROWS.map(([code, short, text, prereqs]) => {
  const [head, topicKey] = code.split('.');
  const t = TOAN_TOPICS[topicKey];
  if (!t) throw new Error(`skills-toan: chủ đề lạ trong mã ${code}`);
  return { code, subject: 'toan', grade: Number(head.slice(1)) as Grade, strand: t.strand, topic: t.topic, text, short, prereqs: prereqs ?? [] };
});
